<template>
 <div class="table-scroll"><table aria-label="砍价参与记录"><thead><tr><th>参与用户</th><th>砍价活动</th><th>发起时间</th><th>帮砍记录 / 所需人数</th><th>当前金额（元）</th><th>状态</th><th>活动结束时间</th><th>操作</th></tr></thead><tbody>
  <tr v-for="entry in entries" :key="entry.key" class="bargain-record-row"><td><img v-if="image(entry.row.avatar_preview)" :src="image(entry.row.avatar_preview)" alt="参与用户头像" /><strong>{{ entry.row.nickname || '历史用户' }}</strong><small>UID {{ entry.row.uid }} · 记录 #{{ entry.row.id }}</small><small v-if="entry.row.deleted_user">已注销</small><small v-if="entry.row.missing_user">用户资料缺失</small></td><td><img v-if="image(entry.row.image_preview)" :src="image(entry.row.image_preview)" alt="活动图片" /><span class="name" :title="entry.row.title">{{ entry.row.title || '历史活动' }}</span><small>活动 #{{ entry.row.bargain_id }}</small><small v-if="entry.row.activity_deleted">活动已删除</small><small v-if="entry.row.activity_missing">活动缺失</small></td>
  <td>{{ time(entry.row.add_time) }}</td><td>{{ entry.row.already_num }} / {{ entry.row.people_num }}<small>剩余 {{ entry.row.num }}</small></td><td>{{ entry.row.now_price }}<small>起价 {{ entry.row.bargain_price }} / 底价 {{ entry.row.bargain_price_min }}</small><small>已砍 {{ entry.row.price }}</small></td><td>{{ status(entry.row) }}<small>历史原值 {{ entry.row.status_raw }}</small><small v-if="entry.row.issues.length" class="bad">{{ entry.row.issues.join('；') }}</small></td><td>{{ time(entry.row.stop_time) }}</td><td><button type="button" :disabled="!enabled || loading" @click="entry.helpers">帮砍详情</button><button v-if="statistics" type="button" :disabled="!enabled || loading || entry.row.bargain_id<=0" @click="entry.statistics">活动统计</button></td></tr>
 </tbody></table><p v-if="!rows.length && !loading" class="empty">暂无砍价参与记录</p><p v-if="loading" role="status">正在读取参与记录…</p></div>
</template>
<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue';
import {bargainPreview as image,bargainRecordStatus as status,type BargainRecord} from '@/api/bargainRecords';
import {bargainReadTime as time} from './bargainReadSession';
const props=defineProps<{rows:BargainRecord[];loading:boolean;enabled:boolean;statistics?:boolean;sourceCurrent?:()=>boolean}>();
const emit=defineEmits<{helpers:[row:BargainRecord];statistics:[row:BargainRecord]}>();
let alive=true;const version=ref(0);onBeforeUnmount(()=>{alive=false;version.value++;});watch(()=>[props.rows,props.loading,props.enabled],()=>version.value++,{flush:'sync'});
const entries=computed(()=>{const generation=version.value,parentCurrent=props.sourceCurrent;return props.rows.map(row=>{const source=JSON.stringify(row),valid=()=>alive&&(parentCurrent?.()??true)&&props.enabled&&!props.loading&&generation===version.value&&props.rows.includes(row)&&JSON.stringify(row)===source;return {key:generation+':'+row.id,row,helpers:()=>{if(valid())emit('helpers',row);},statistics:()=>{if(valid()&&props.statistics&&row.bargain_id>0)emit('statistics',row);}};});});
</script>
<style scoped>
.table-scroll{max-width:100%;overflow-x:auto}table{width:100%;min-width:1120px;border-collapse:collapse;background:#fff;font-size:13px}th,td{text-align:left;padding:12px;border:1px solid #e5e7eb;vertical-align:top}th{background:#f7f8fa;white-space:nowrap}th:nth-child(1){min-width:155px}th:nth-child(2){min-width:210px}td{line-height:1.65}td img{width:36px;height:36px;object-fit:cover;float:left;margin:0 8px 4px 0;border-radius:4px}small{display:block;color:#747b87;font-size:12px}.name{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;overflow-wrap:anywhere;max-width:280px}button{font:inherit;padding:5px 8px;margin:0 5px 5px 0;background:#fff;border:1px solid #dcdfe6;border-radius:4px;color:#356ac3;cursor:pointer}button:disabled{opacity:.5;cursor:default}.empty{padding:24px;text-align:center;color:#909399}.bad{color:#c45656}
</style>
